    answers: ['facebook cover image looks blurry', 'instagram photo blurry after upload', 'why is my image blurry on instagram', 'why does my picture look blurry on facebook', 'image quality lost after upload', 'linkedin banner blurry', 'best export settings for instagram'],
    related: ['social-media-sizes-and-safe-zones', 'export-for-screen', 'size-presets', 'fix-a-blurry-image'],
    keywords: 'blurry after upload instagram facebook linkedin compression resize export settings png jpg quality platform size screenshot data saver',
